-- Adição da análise por IA ao esquema padronizado de orçamentos, Firebird 4/5.
-- Preferir --migrate-database, que instala de forma repetível esta estrutura.
-- Alternativa manual de execução única, com backup, API parada e alvo conferido.
-- Não altera nem remove registros das tabelas existentes. Requer ORCAMENTOREVISAO.
-- Executar no isql com -b (parar no primeiro erro). Não repetir se já instalado.
SET AUTODDL OFF;
CREATE TABLE ORCAMENTOANALISE (CODORCAMENTOANALISE BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, CODORCAMENTO BIGINT NOT NULL, REVISAO INTEGER NOT NULL, VERSAOORCAMENTO BIGINT NOT NULL, STATUS VARCHAR(20) CHARACTER SET ASCII NOT NULL, ENTRADA BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, RESULTADO BLOB SUB_TYPE TEXT CHARACTER SET UTF8, ERRO VARCHAR(500) CHARACTER SET UTF8, MODELO VARCHAR(80) CHARACTER SET ASCII NOT NULL, CODUSUARIO INTEGER NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, DTHRINICIO TIMESTAMP, DTHRFIM TIMESTAMP, CHAVEEXECUCAO VARCHAR(36) CHARACTER SET ASCII, CONSTRAINT PK_ORCAMENTOANALISE PRIMARY KEY(CODORCAMENTOANALISE), CONSTRAINT FK_ORCAMENTOANALISE_REVISAO FOREIGN KEY(CODORCAMENTO,REVISAO) REFERENCES ORCAMENTOREVISAO(CODORCAMENTO,NUMERO), CONSTRAINT CK_ORCAMENTOANALISE_STATUS CHECK(STATUS IN ('pendente','executando','concluida','erro','cancelada','aplicada')));
CREATE INDEX IX_ORCAMENTOANALISE_FILA ON ORCAMENTOANALISE(STATUS,CODORCAMENTOANALISE);
COMMIT;
SET AUTODDL ON;

